type AssetPack = Partial<Record<RacerName, string>>;
type SoundName = 'roll' | 'move' | 'event' | 'finish' | 'click';
type PendingAbility = { action: AbilityActionId; targetId?: string };
type DiceRoll = { racerId: string; from: number; to: number; value: number | null; phase: 'rolling' | 'result' };
type DraftState = { pick: number; startPlayer: number; pool: RacerName[] };
type AbilityActivation = { racer: RacerState; ownerName: string; label: string };
const assetStorageKey = 'magical-athlete-asset-pack-v1';
const assetSlug = (value: string) => value.toLowerCase().replace(/\.[^.]+$/, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const cardSlug = (name: RacerName) => assetSlug(name);
const bytesToDataUrl = (data: Uint8Array, mime: string) => { let binary = ''; for (let index = 0; index < data.length; index += 0x8000) binary += String.fromCharCode(...data.subarray(index, index + 0x8000)); return `data:${mime};base64,${btoa(binary)}`; };
const loadStoredAssetPack = (): AssetPack => { if (typeof window === 'undefined') return {}; try { const stored = window.localStorage.getItem(assetStorageKey); return stored ? JSON.parse(stored) as AssetPack : {}; } catch { return {}; } };
const snakeOrder = (playerCount: number, startPlayer: number) => { const forward = Array.from({ length: playerCount }, (_, index) => (startPlayer + index) % playerCount); return [...forward, ...[...forward].reverse()]; };
const draftOrder = (playerCount: number, startPlayer: number) => [...snakeOrder(playerCount, startPlayer), ...snakeOrder(playerCount, (startPlayer + 1) % playerCount)];
const shuffleNames = (names: RacerName[]) => [...names].sort(() => Math.random() - 0.5);
const drawDraftPool = (playerCount: number, used: RacerName[] = []) => { const usedSet = new Set(used); return shuffleNames(RACERS.filter((racer) => !usedSet.has(racer.name)).map((racer) => racer.name)).slice(0, playerCount * 2); };

function useSounds(enabled: boolean) {
  const contextRef = useRef<AudioContext | null>(null);
  return useCallback((name: SoundName) => {
    if (!enabled || typeof window === 'undefined') return;
    const AudioContextCtor = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AudioContextCtor) return;
    const context = contextRef.current ?? new AudioContextCtor(); contextRef.current = context;
    if (context.state === 'suspended') void context.resume();
    const notes: Record<SoundName, [number, number]> = { click: [180, 0.04], roll: [260, 0.1], move: [420, 0.08], event: [620, 0.13], finish: [820, 0.22] };
    const [frequency, duration] = notes[name]; const oscillator = context.createOscillator(); const gain = context.createGain();
    oscillator.type = name === 'finish' ? 'triangle' : 'sine'; oscillator.frequency.setValueAtTime(frequency, context.currentTime); oscillator.frequency.exponentialRampToValueAtTime(frequency * (name === 'roll' ? 1.45 : 1.08), context.currentTime + duration);
    gain.gain.setValueAtTime(0.0001, context.currentTime); gain.gain.exponentialRampToValueAtTime(name === 'finish' ? 0.18 : 0.08, context.currentTime + 0.015); gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + duration);
    oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + duration + 0.02);
  }, [enabled]);
}

function Token({ card, assetUrl, size = 'normal' }: { card: RacerCard; assetUrl?: string; size?: 'small' | 'normal' }) {
  // Blob URLs come from the user-selected ZIP and cannot be optimized by next/image.
  // eslint-disable-next-line @next/next/no-img-element
  if (assetUrl) return <img className={`card-token card-token-${size}`} src={assetUrl} alt="" aria-hidden="true" />;
  return <span className={`token token-${size}`} style={{ background: `linear-gradient(145deg, ${card.color}, #151217)` }} aria-hidden="true"><span>{card.name.slice(0, 1)}</span></span>;
}

function Card({ card, selected, onClick, locale, assetUrl, onSound }: { card: RacerCard; selected: boolean; onClick: () => void; locale: Locale; assetUrl?: string; onSound: () => void }) {
  return <button className={`racer-card ${selected ? 'is-selected' : ''}`} onClick={() => { onSound(); onClick(); }} style={{ ['--accent' as string]: card.color }} aria-pressed={selected}>
    <div className="card-top"><Token card={card} assetUrl={assetUrl} /><span className="card-index">{String(card.token + 1).padStart(2, '0')}</span></div>
    <div className="card-title">{locale === 'zh' ? card.zhName : card.name}</div><div className="card-tagline">{locale === 'zh' ? '角色能力卡' : card.tagline}</div>
    <div className="card-ability"><span>{locale === 'zh' ? '能力' : 'ABILITY'}</span>{locale === 'zh' ? card.zhAbility : card.ability}</div>
  </button>;
}

function DraftAssignment({ player, assetPack, locale }: { player: GameState['players'][number]; assetPack: AssetPack; locale: Locale }) {
  return <div className="draft-assignment"><div className="assignment-heading"><span>{player.name}</span><small>{player.team.length} / 4</small></div><div className="assignment-list">{player.team.length ? player.team.map((name) => <div className="assignment-card" key={name}><Token card={racerByName(name)} assetUrl={assetPack[name]} size="small" /><span>{displayRacerName(name, locale)}</span></div>) : <small className="assignment-empty">{locale === 'zh' ? '尚未选角' : 'No picks yet'}</small>}</div></div>;
}

function RaceSelectScreen({ state, locale, assetPack, selection, onToggle, onConfirm, onSound }: { state: GameState; locale: Locale; assetPack: AssetPack; selection: RacerName[]; onToggle: (name: RacerName) => void; onConfirm: () => void; onSound: () => void }) {
  const tx = copy[locale]; const player = state.players[state.raceSelectPlayer]; const slots = raceSlots(state.players.length); const board = state.board === 'Mild Mile' ? tx.mild : tx.wild;
  return <main className="app-shell"><header className="app-header"><div className="brand-lockup"><span className="brand-mark">MA</span><span className="brand-type">MAGICAL<br />ATHLETE</span></div><span className="race-pill">{tx.race.replace('{n}', String(state.raceNumber))} <span>·</span> {board}</span><div className="header-meta"><span>{player?.name}</span></div></header><section className="draft-shell race-select-shell"><div className="section-heading"><div><p className="eyebrow">{tx.raceSelect}</p><h1>{player?.isAi ? tx.draftChoosing : player?.name}</h1><small>{tx.raceSelectHint} · {tx.raceSelectCount.replace('{n}', String(slots))}</small></div><div className="draft-count"><strong>{selection.length}</strong><span>/ {slots}<br />{locale === 'zh' ? '本场出战' : 'for this race'}</span></div></div><div className="draft-grid race-select-grid">{(player?.team ?? []).map((name) => { const card = racerByName(name); return <Card key={card.name} card={card} selected={selection.includes(card.name)} onClick={() => onToggle(card.name)} locale={locale} assetUrl={assetPack[card.name]} onSound={onSound} />; })}</div><div className="draft-assignments">{state.players.map((item) => <div className="draft-assignment" key={item.id}><div className="assignment-heading"><span>{item.name}</span><small>{(state.raceSelections[item.id] ?? []).length} / {slots}</small></div><div className="assignment-list"><small>{item.id === player?.id ? (selection.length ? selection.map((name) => displayRacerName(name, locale)).join(' · ') : locale === 'zh' ? '尚未选择' : 'Not selected') : state.raceSelections[item.id]?.length ? tx.raceSelectWaiting : item.isAi ? tx.draftChoosing : locale === 'zh' ? '等待选择' : 'Waiting'}</small></div></div>)}</div><div className="draft-bar"><span>{player?.isAi ? tx.draftChoosing : `${player?.name} · ${tx.raceSelectCount.replace('{n}', String(slots))}`}</span><button className="primary-cta" disabled={Boolean(player?.isAi) || selection.length !== slots} onClick={onConfirm}>{tx.confirm}<span>↗</span></button></div></section></main>;
}

const cells = Array.from({ length: 31 }, (_, position) => {
  if (position === 0) return { x: 30, y: 40, w: 150, h: 64 };
  if (position <= 12) return { x: 180 + (position - 1) * 70, y: 40, w: 70, h: 64 };
  if (position <= 15) return { x: 950, y: 104 + (position - 13) * 64, w: 70, h: 64 };
  if (position === 16) return { x: 880, y: 232, w: 70, h: 64 };
  if (position <= 29) return { x: 816 - (position - 17) * 64, y: 232, w: 64, h: 64 };
  return { x: 48, y: 168, w: 64, h: 64 };
});
const spaceColors = ['#6ab8e5', '#f1b62a', '#56a94c', '#55a4e0', '#f05a21', '#e86ccf'];
const effectLabel: Record<string, [string, string]> = { star: ['★', '★'], trip: ['绊倒', 'TRIP'], '+1': ['+1', '+1'], '+2': ['+2', '+2'], '+3': ['+3', '+3'], '-2': ['−2', '−2'], '-4': ['−4', '−4'] };
type MovementAnimation = { racerId: string; from: number; to: number; position: number };

function Board({ state, locale, assetPack, movement, dice }: { state: GameState; locale: Locale; assetPack: AssetPack; movement: MovementAnimation | null; dice: DiceRoll | null }) {
  const racersByCell = state.racers.filter((r) => !r.eliminated && (r.finished === null || movement?.racerId === r.id || dice?.racerId === r.id)).reduce<Record<number, RacerState[]>>((result, racer) => { const isMovementRacer = movement?.racerId === racer.id; const isDiceRacer = !isMovementRacer && dice?.racerId === racer.id; const key = Math.min(isMovementRacer ? movement.position : isDiceRacer ? dice.from : racer.position, 30); (result[key] ??= []).push(racer); return result; }, {});
  return <div className="board-wrap"><svg className="race-board" viewBox="0 0 1040 348" role="img" aria-label={`${displayBoardName(state.board, locale)} ${locale === 'zh' ? '赛道' : 'race track'}`}>
    <title>{displayBoardName(state.board, locale)} · {locale === 'zh' ? '赛道地图' : 'race track'}</title><rect width="1040" height="348" rx="28" fill="#19151d" /><rect x="14" y="24" width="1012" height="300" rx="28" fill="#151218" stroke="#f6f0e8" strokeWidth="4" />
    <path d="M46 187 C175 140 260 150 378 184 S618 232 796 172 S944 149 1000 187 L1000 268 C887 306 776 306 625 270 S306 213 46 271Z" fill="#8c47b6" opacity=".82" /><path d="M78 188 C149 156 211 148 269 169 C230 178 205 203 173 214 C135 218 106 209 78 188Z" fill="#2d7b4a" /><path d="M210 175 l24 -48 24 48Z M243 175 l22 -59 25 59Z M817 175 l22 -58 24 58Z M858 172 l27 -45 23 45Z" fill="#1e7546" />
    <text x="520" y="213" textAnchor="middle" fill="#f7f3ed" fontSize="76" fontWeight="1000" letterSpacing="-8">{displayBoardName(state.board, locale)}</text><text x="520" y="244" textAnchor="middle" fill="#f9d91b" fontSize="12" fontWeight="900" letterSpacing="5">{locale === 'zh' ? '掷骰 · 移动 · 混乱' : 'ROLL · MOVE · CHAOS'}</text>
    {cells.map((cell, position) => { const effect = state.board === 'Wild Wilds' ? wildEffects[position] : undefined; const fill = position === 0 ? '#f7f1e9' : position === 30 ? '#f7d72c' : spaceColors[position % spaceColors.length]; return <g key={position}><rect x={cell.x} y={cell.y} width={cell.w} height={cell.h} rx="3" fill={fill} stroke="#171318" strokeWidth="4" />{position === 0 ? <text x={cell.x + cell.w / 2} y={cell.y + 40} textAnchor="middle" fill="#171318" fontSize="25" fontWeight="1000">{locale === 'zh' ? '起点' : 'START'}</text> : position === 30 ? <text x={cell.x + cell.w / 2} y={cell.y + 36} textAnchor="middle" fill="#171318" fontSize="18" fontWeight="1000">{locale === 'zh' ? '终点' : 'FINISH'}</text> : <text x={cell.x + 8} y={cell.y + 18} fill="#171318" fontSize="11" fontWeight="900">{position}</text>}{effect ? <g className="space-effect"><circle cx={cell.x + cell.w - 17} cy={cell.y + cell.h - 16} r="15" fill="#171318" opacity=".84" /><text x={cell.x + cell.w - 17} y={cell.y + cell.h - 11} textAnchor="middle" fill="#fff" fontSize={effect === 'trip' ? '7' : '14'} fontWeight="1000">{effectLabel[effect][locale === 'zh' ? 0 : 1]}</text></g> : null}</g>; })}
    {Object.entries(racersByCell).flatMap(([cellIndex, racers]) => racers.map((racer, index) => { const cell = cells[Number(cellIndex)]; const card = racerByName(racer.name); const owner = state.players.find((player) => player.id === racer.ownerId); const ownerLabel = owner?.name ?? ''; const tagWidth = Math.max(42, Math.min(104, ownerLabel.length * 8 + 18)); const row = Math.floor(index / 3); const rowStart = row * 3; const rowSize = Math.min(3, racers.length - rowStart); const column = index % 3; const dx = cell.x + cell.w / 2 + (column - (rowSize - 1) / 2) * 24; const dy = cell.y + cell.h / 2 + row * 20 - (Math.ceil(racers.length / 3) - 1) * 10; const isMovementRacer = movement?.racerId === racer.id; const isDiceRacer = !isMovementRacer && dice?.racerId === racer.id; const visualPosition = isMovementRacer ? movement.position : isDiceRacer ? dice.from : racer.position; const previousStep = isMovementRacer && movement.position !== movement.from ? movement.position - Math.sign(movement.to - movement.from) : visualPosition; const oldCell = cells[Math.min(Math.max(previousStep, 0), 30)]; const oldDx = oldCell.x + oldCell.w / 2; const oldDy = oldCell.y + oldCell.h / 2; const url = assetPack[racer.name]; return <g key={racer.id} transform={`translate(${dx} ${dy})`} className={`board-piece ${isMovementRacer ? 'is-moving' : ''}`}>{isMovementRacer && visualPosition !== movement.from && previousStep !== visualPosition ? <animateTransform key={`${racer.id}-${visualPosition}`} attributeName="transform" attributeType="XML" type="translate" from={`${oldDx} ${oldDy}`} to={`${dx} ${dy}`} dur="0.13s" fill="freeze" /> : null}<g className={racer.tripped ? 'piece-tripped' : undefined}><g className="board-owner-tag"><rect x={-tagWidth / 2} y="-48" width={tagWidth} height="17" rx="8.5" fill={owner?.color ?? card.color} stroke="#171318" strokeWidth="2" /><path d={`M ${-5} -31 L 0 -25 L 5 -31 Z`} fill={owner?.color ?? card.color} stroke="#171318" strokeWidth="2" /><text x="0" y="-36" textAnchor="middle" fill="#fff" fontSize="8" fontWeight="1000">{ownerLabel}</text></g>{url ? <image href={url} x="-21" y="-29" width="42" height="58" preserveAspectRatio="xMidYMid meet" className="piece-image" /> : <><circle r="21" fill={card.color} stroke="#fff" strokeWidth="3" /><text y="6" textAnchor="middle" fill="#fff" fontSize="18" fontWeight="1000">{card.name.slice(0, 1)}</text></>}</g><title>{displayRacerName(card.name, locale)} · {visualPosition}/30</title></g>; }))}
  </svg><div className="board-caption"><span><i className="legend-dot mild-dot" /> {locale === 'zh' ? 'SVG 格子与移动一致' : 'SVG cells mirror movement'}</span><span><i className="legend-dot star-dot" /> {state.board === 'Wild Wilds' ? (locale === 'zh' ? '星星：+1 分' : 'Star +1 point') : (locale === 'zh' ? '温和大道：无事件' : 'Mild: no events')}</span><span><i className="legend-dot trip-dot" /> {locale === 'zh' ? '绊倒：跳过下次主移动' : 'Trip'}</span></div></div>;
}

