function AbilityPanel({ state, racer, locale, activeAction, prediction, onAction, onTarget, onPrediction, onCancel }: { state: GameState; racer?: RacerState; locale: Locale; activeAction: AbilityActionId | null; prediction: number; onAction: (action: AbilityActionId) => void; onTarget: (action: AbilityActionId, targetId: string) => void; onPrediction: (value: number) => void; onCancel: () => void }) {
  const options = abilityActions(state, racer);
  const tx = copy[locale];
  return <div className="ability-controls"><div className="ability-control-title"><span>{tx.abilityAction}</span><small>{tx.abilityAuto}</small></div>{options.length ? options.map((option) => <div className="ability-option" key={option.id}><button className={`ability-button ${activeAction === option.id ? 'is-armed' : ''}`} onClick={() => onAction(option.id)}>{abilityLabels[option.id][locale === 'zh' ? 0 : 1]}{activeAction === option.id && (option.id === 'rocket' || option.id === 'magician' || option.id === 'genius') ? ` · ${tx.armed}` : ''}</button>{activeAction === option.id && option.targetIds.length ? <div className="target-list"><span>{tx.chooseTarget}</span>{option.targetIds.map((targetId) => { const target = state.racers.find((item) => item.id === targetId); return target ? <button key={targetId} className="target-button" onClick={() => onTarget(option.id, targetId)}>{displayRacerName(target.name, locale)} · {target.position}</button> : null; })}</div> : null}{activeAction === option.id && option.id === 'genius' ? <div className="prediction-list"><span>{tx.prediction}</span>{[1, 2, 3, 4, 5, 6].map((value) => <button key={value} className={prediction === value ? 'selected' : ''} onClick={() => onPrediction(value)}>{value}</button>)}</div> : null}</div>) : <small className="ability-auto-note">{tx.abilityAuto}</small>}{activeAction ? <button className="ability-cancel" onClick={onCancel}>{tx.cancel}</button> : null}</div>;
}

function DiceOverlay({ value, phase, locale }: { value: number | null; phase: 'rolling' | 'result'; locale: Locale }) {
  return <div className="dice-overlay" role="status" aria-live="assertive"><div className="dice-overlay-card"><span className="dice-overlay-kicker">{locale === 'zh' ? '主移动' : 'MAIN MOVE'}</span><div className={`dice-visual ${phase}`}>{phase === 'rolling' ? <span className="dice-shuffle">⚄</span> : value ?? '—'}</div><strong>{phase === 'rolling' ? (locale === 'zh' ? '掷骰中…' : 'Rolling…') : `${locale === 'zh' ? '掷出' : 'Rolled'} ${value ?? '—'}`}</strong></div></div>;
}

function AbilityConfirmOverlay({ action, racer, target, prediction, locale, onPrediction, onConfirm, onCancel }: { action: AbilityActionId; racer: RacerState; target?: RacerState; prediction: number; locale: Locale; onPrediction: (value: number) => void; onConfirm: () => void; onCancel: () => void }) {
  const isPrediction = action === 'genius';
  return <div className="ability-overlay" role="dialog" aria-modal="true" aria-labelledby="ability-confirm-title"><div className="ability-signal"><span>{locale === 'zh' ? '能力发动' : 'ABILITY'}</span><b>{locale === 'zh' ? '确认后执行' : 'CONFIRM TO EXECUTE'}</b></div><div className="ability-confirm-card"><span className="ability-confirm-kicker">{locale === 'zh' ? '是否发动技能？' : 'ACTIVATE ABILITY?'}</span><h2 id="ability-confirm-title">{abilityLabels[action][locale === 'zh' ? 0 : 1]}</h2><p>{locale === 'zh' ? racerByName(racer.name).zhAbility : racerByName(racer.name).ability}</p>{target ? <div className="ability-target-preview">{locale === 'zh' ? '目标' : 'Target'}：{displayRacerName(target.name, locale)} · {target.position}</div> : null}{isPrediction ? <div className="confirm-prediction"><span>{locale === 'zh' ? '预测点数' : 'Predict'}</span>{[1, 2, 3, 4, 5, 6].map((value) => <button key={value} className={prediction === value ? 'selected' : ''} onClick={() => onPrediction(value)}>{value}</button>)}</div> : null}<div className="ability-confirm-actions"><button className="ability-cancel" onClick={onCancel}>{locale === 'zh' ? '暂不发动' : 'Cancel'}</button><button className="primary-cta" onClick={onConfirm}>{locale === 'zh' ? '确认发动' : 'Activate'}<span>↗</span></button></div></div></div>;
}

function AbilityActivationOverlay({ activation, locale, assetUrl, onDone }: { activation: AbilityActivation; locale: Locale; assetUrl?: string; onDone: () => void }) {
  useEffect(() => { const timer = window.setTimeout(onDone, 860); return () => window.clearTimeout(timer); }, [onDone]);
  const card = racerByName(activation.racer.name);
  return <div className="ability-activation-overlay" role="status" aria-live="assertive"><div className="ability-activation-signal"><span>{locale === 'zh' ? '技能发动' : 'ABILITY ACTIVATED'}</span><b>{activation.ownerName}</b></div><div className="ability-activation-card"><Token card={card} assetUrl={assetUrl} /><div className="ability-activation-copy"><small>{locale === 'zh' ? '现在执行' : 'NOW EXECUTING'}</small><h2>{activation.label}</h2><p>{locale === 'zh' ? card.zhAbility : card.ability}</p></div></div></div>;
}

function TripOverlay({ racer, locale, assetUrl }: { racer: RacerState; locale: Locale; assetUrl?: string }) {
  const card = racerByName(racer.name);
  return <div className="trip-overlay" role="status" aria-live="assertive"><div className="trip-signal"><span>{locale === 'zh' ? '状态变化' : 'STATUS CHANGE'}</span><b>{locale === 'zh' ? '绊倒！' : 'TRIPPED!'}</b></div><div className="trip-card"><Token card={card} assetUrl={assetUrl} /><div className="trip-copy"><small>{locale === 'zh' ? '本回合跳过主移动' : 'SKIP THIS MAIN MOVE'}</small><h2>{locale === 'zh' ? '绊倒' : 'TRIPPED'}</h2><p>{locale === 'zh' ? `${displayRacerName(card.name, locale)} 绊倒了，正在跳过本回合。` : `${card.name} is tripped and skips this turn.`}</p></div></div></div>;
}

function MastermindOverlay({ racers, locale, assetPack, selectedId, onSelect, onConfirm }: { racers: RacerState[]; locale: Locale; assetPack: AssetPack; selectedId: string | null; onSelect: (id: string) => void; onConfirm: () => void }) {
  return <div className="mastermind-overlay" role="dialog" aria-modal="true" aria-labelledby="mastermind-title"><div className="mastermind-signal"><span>{locale === 'zh' ? '比赛开始前' : 'BEFORE THE RACE'}</span><b>{locale === 'zh' ? '阴谋家发动能力' : 'MASTERMIND ACTIVATES'}</b></div><div className="mastermind-card"><span className="ability-confirm-kicker">{locale === 'zh' ? '预测谁会获胜？' : 'WHO WILL WIN?'}</span><h2 id="mastermind-title">{locale === 'zh' ? '做出你的预言' : 'Make your prediction'}</h2><p>{locale === 'zh' ? '选择一名角色。若预测正确，比赛会立即结束，阴谋家获得第 2 名。' : 'Choose a racer. If correct, the race ends immediately and Mastermind finishes 2nd.'}</p><div className="mastermind-options">{racers.map((racer) => { const card = racerByName(racer.name); return <button key={racer.id} className={selectedId === racer.id ? 'selected' : ''} onClick={() => onSelect(racer.id)}><Token card={card} assetUrl={assetPack[racer.name]} size="small" /><span>{displayRacerName(racer.name, locale)}</span></button>; })}</div><button className="primary-cta" disabled={!selectedId} onClick={onConfirm}>{locale === 'zh' ? '确认预言' : 'Confirm prediction'}<span>↗</span></button></div></div>;
}

function PlayerNameOverlay({ locale, value, onChange, onConfirm, onCancel }: { locale: Locale; value: string; onChange: (value: string) => void; onConfirm: () => void; onCancel: () => void }) {
  const isZh = locale === 'zh';
  return <div className="name-overlay" role="dialog" aria-modal="true" aria-labelledby="player-name-title"><form className="name-card" onSubmit={(event) => { event.preventDefault(); onConfirm(); }}><span className="ability-confirm-kicker">{isZh ? '开始前设置' : 'BEFORE WE START'}</span><h2 id="player-name-title">{isZh ? '你的玩家名称？' : 'Your player name?'}</h2><p>{isZh ? '这个名称会显示在计分板、选角标签和技能提示中。' : 'This name appears on the scoreboard, draft tags, and ability alerts.'}</p><input autoFocus value={value} maxLength={18} placeholder={isZh ? '请输入名称' : 'Enter your name'} onChange={(event) => onChange(event.target.value)} /><div className="name-actions"><button type="button" className="ability-cancel" onClick={onCancel}>{isZh ? '取消' : 'Cancel'}</button><button type="submit" className="primary-cta" disabled={!value.trim()}>{isZh ? '确认并开始' : 'Confirm & start'}<span>↗</span></button></div></form></div>;
}

function HomeScreen({ locale, setLocale, mode, setMode, onStart, soundOn, setSoundOn, onUpload, assetCount, uploadMessage }: { locale: Locale; setLocale: (x: Locale) => void; mode: GameMode; setMode: (x: GameMode) => void; onStart: () => void; soundOn: boolean; setSoundOn: (x: boolean) => void; onUpload: (file: File) => void; assetCount: number; uploadMessage: string | null }) {
  const tx = copy[locale]; const modes: Array<[GameMode, string, string, string, string]> = [['ai', '01', tx.ai, tx.aiDesc, '✦'], ['local', '02', tx.local, tx.localDesc, '◒'], ['online', '03', tx.online, tx.onlineDesc, '↗']];
  return <main className="home-shell"><div className="home-left"><header className="home-nav"><div className="brand-lockup"><span className="brand-mark">MA</span><span className="brand-type">MAGICAL<br />ATHLETE</span></div><div className="nav-actions"><button className="sound-button" onClick={() => setSoundOn(!soundOn)} aria-pressed={soundOn}>{soundOn ? '◉' : '○'} {soundOn ? tx.soundOn : tx.soundOff}</button><button className="text-button" onClick={() => setLocale(locale === 'zh' ? 'en' : 'zh')}>{locale === 'zh' ? 'EN / 中文' : '中文 / EN'}</button></div></header><div className="hero-copy"><p className="eyebrow">{tx.kicker}</p><h1>{tx.title}</h1><p>{tx.subtitle}</p></div><div className="hero-actions"><button className="primary-cta" onClick={onStart}>{tx.start}<span>↗</span></button><span className="keyboard-hint">{tx.space}</span></div><section className="asset-panel"><div className="asset-copy"><p className="eyebrow">{tx.assetTitle}</p><strong>{assetCount ? tx.assetReady.replace('{n}', String(assetCount)) : tx.assetNone}</strong><small>{tx.assetHint}</small><small>{tx.assetPrivate} · {tx.packExample}</small>{uploadMessage ? <em>{uploadMessage}</em> : null}</div><label className="upload-button">{tx.assetPick}<input type="file" accept=".zip,application/zip" onChange={(event) => { const file = event.target.files?.[0]; if (file) onUpload(file); event.currentTarget.value = ''; }} /></label></section><div className="home-footer"><span>{tx.private}</span><span>{tx.source}</span></div></div><div className="home-right"><div className="poster"><div className="poster-red"></div><div className="poster-track"><span>{locale === 'zh' ? '起点' : 'START'}</span><b>{locale === 'zh' ? <>荒野<br />狂奔</> : <>WILD<br />WILDS</>}</b><i>★</i><i>{locale === 'zh' ? '绊倒' : 'TRIP'}</i></div><div className="poster-word">{locale === 'zh' ? <>掷骰<br /><span>向前</span><br />混乱</> : <>ROLL<br /><span>FOR</span><br />CHAOS</>}</div><div className="poster-number">01</div></div><div className="mode-panel"><p className="eyebrow">{tx.chooseMode}</p>{modes.map(([id, n, title, desc, icon]) => <button key={id} className={`mode-row ${mode === id ? 'active' : ''}`} onClick={() => setMode(id)}><span className="mode-number">{n}</span><span className="mode-icon">{icon}</span><span className="mode-copy"><strong>{title}</strong><small>{desc}</small></span><span className="mode-arrow">→</span></button>)}</div></div></main>;
}

export default function Home() {
  const [locale, setLocale] = useState<Locale>('zh'); const [mode, setMode] = useState<GameMode>('ai'); const [state, setState] = useState<GameState | null>(null); const [draft, setDraft] = useState<DraftState | null>(null); const [raceChoice, setRaceChoice] = useState<RacerName[]>([]); const [tripNotice, setTripNotice] = useState<RacerState | null>(null); const [mastermindTarget, setMastermindTarget] = useState<string | null>(null); const [copied, setCopied] = useState(false); const [soundOn, setSoundOn] = useState(true); const [assetPack, setAssetPack] = useState<AssetPack>({}); const [uploadMessage, setUploadMessage] = useState<string | null>(null); const [movement, setMovement] = useState<MovementAnimation | null>(null); const [diceRoll, setDiceRoll] = useState<DiceRoll | null>(null); const [pendingAbility, setPendingAbility] = useState<PendingAbility | null>(null); const [abilityActivation, setAbilityActivation] = useState<AbilityActivation | null>(null); const [namePrompt, setNamePrompt] = useState(false); const [playerName, setPlayerName] = useState(''); const [toast, setToast] = useState<string | null>(null); const [activeAbility, setActiveAbility] = useState<AbilityActionId | null>(null); const [prediction, setPrediction] = useState(1); const tx = copy[locale]; const playSound = useSounds(soundOn);
  useEffect(() => { const timer = window.setTimeout(() => setAssetPack(loadStoredAssetPack()), 0); return () => window.clearTimeout(timer); }, []);
  const startDraft = (game: GameState) => { setState(game); setDraft({ pick: 0, startPlayer: 0, pool: drawDraftPool(game.players.length) }); };
  const start = () => { playSound('click'); if (!playerName.trim()) { setNamePrompt(true); return; } const game = createGame(mode, locale); game.players[0].name = playerName.trim(); if (game.phase === 'draft') startDraft(game); else { setState(game); setDraft(null); } setRaceChoice([]); setTripNotice(null); setMastermindTarget(null); setToast(null); setActiveAbility(null); setPendingAbility(null); setAbilityActivation(null); setDiceRoll(null); setMovement(null); };
  const chooseDraftRacer = (name: RacerName, byAi = false) => {
    if (!state || state.phase !== 'draft' || !draft) return;
    const order = draftOrder(state.players.length, draft.startPlayer); const actorIndex = order[draft.pick]; const actor = state.players[actorIndex];
    if (!actor || (!byAi && actor.isAi) || !draft.pool.includes(name)) return;
    const players = state.players.map((player, index) => index === actorIndex ? { ...player, team: [...player.team, name] } : player); const next = { ...state, players }; const nextPick = draft.pick + 1; const totalPicks = state.players.length * 4;
    playSound(byAi ? 'event' : 'click');
    if (nextPick >= totalPicks) { setDraft(null); setState(beginRace(next)); setToast(locale === 'zh' ? '蛇形选角完成，四场比赛正式开始！' : 'Snake draft complete. Let the four races begin!'); return; }
    const poolSize = state.players.length * 2; const used = players.flatMap((player) => player.team); const nextPool = nextPick % poolSize === 0 ? drawDraftPool(state.players.length, used) : draft.pool.filter((racer) => racer !== name);
    setState(next); setDraft({ ...draft, pick: nextPick, pool: nextPool }); setToast(`${displayRacerName(name, locale)} · ${actor.name}`);
  };
  const handleUpload = async (file: File) => { try { const files = unzipSync(new Uint8Array(await file.arrayBuffer())); const next: AssetPack = {}; Object.entries(files).forEach(([path, data]) => { const extension = path.toLowerCase().match(/\.(png|jpe?g|webp|gif)$/)?.[1]; if (!extension) return; const name = RACERS.find((racer) => cardSlug(racer.name) === assetSlug(path.split('/').pop() ?? '')); if (name) { const mime = `image/${extension === 'jpg' ? 'jpeg' : extension}`; next[name.name] = bytesToDataUrl(data, mime); } }); if (!Object.keys(next).length) throw new Error('empty'); setAssetPack((current) => { const merged = { ...current, ...next }; try { localStorage.setItem(assetStorageKey, JSON.stringify(merged)); } catch { /* Storage may be unavailable or full; the current session still works. */ } return merged; }); setUploadMessage(null); } catch { setUploadMessage(tx.uploadError); } };
  const commitRaceChoice = (names: RacerName[]) => { if (!state || state.phase !== 'race-select') return; const player = state.players[state.raceSelectPlayer]; const slots = raceSlots(state.players.length); if (!player || names.length !== slots || names.some((name) => !player.team.includes(name))) return; const selections = { ...state.raceSelections, [player.id]: names }; const nextPlayer = state.raceSelectPlayer + 1; playSound(player.isAi ? 'event' : 'click'); setRaceChoice([]); if (nextPlayer >= state.players.length) { setState(startRace({ ...state, raceSelections: selections }, selections)); setToast(locale === 'zh' ? `第 ${state.raceNumber} 场出战角色已确定。` : `Race ${state.raceNumber} racers are ready.`); } else { setState({ ...state, raceSelections: selections, raceSelectPlayer: nextPlayer }); setToast(`${player.name} · ${names.map((name) => displayRacerName(name, locale)).join('、')}`); } };
  const toggleRaceChoice = (name: RacerName) => { if (!state || state.phase !== 'race-select') return; const player = state.players[state.raceSelectPlayer]; if (!player || player.isAi || !player.team.includes(name)) return; const slots = raceSlots(state.players.length); setRaceChoice((current) => current.includes(name) ? current.filter((item) => item !== name) : current.length < slots ? [...current, name] : current); };
  const beginPieceMovement = (racerId: string, from: number, to: number) => { if (from !== to) setMovement({ racerId, from, to, position: from }); };
  const queueDice = (racerId: string, from: number, to: number, value: number | null) => { setDiceRoll({ racerId, from, to, value, phase: 'rolling' }); };
  const handleRoll = (ability?: AbilityActionId) => { if (!state || state.phase !== 'race' || movement || diceRoll || mastermindPromptVisible) return; const racer = state.racers.find((r) => r.ownerId === state.players[state.currentPlayer]?.id && !r.eliminated && r.finished === null); if (!racer || racer.tripped) return; const from = racer.position; playSound('roll'); const chosen = ability ?? activeAbility ?? undefined; const next = takeTurn(state, undefined, { ability: chosen, prediction: chosen === 'genius' ? prediction : undefined }); const moved = next.racers.find((item) => item.id === racer.id); setState(next); setActiveAbility(null); setToast(next.log[next.log.length - 1] ?? null); if (moved) queueDice(moved.id, from, moved.position, moved.lastRoll); };
  const handleAbility = (action: AbilityActionId, targetId?: string) => { if (!state || !currentRacer || activePlayer?.isAi || movement || diceRoll || mastermindPromptVisible) return; const targetOption = abilityActions(state, currentRacer).find((option) => option.id === action); if (!targetId && targetOption?.targetIds.length) { setActiveAbility((current) => current === action ? null : action); return; } if (action === 'rocket' || action === 'magician' || action === 'genius' || action === 'legs' || targetId) { setPendingAbility({ action, targetId }); return; } };
  const confirmAbility = () => { if (!state || !currentRacer || !pendingAbility) return; const { action, targetId } = pendingAbility; const ownerName = state.players.find((player) => player.id === currentRacer.ownerId)?.name ?? ''; const label = abilityLabels[action][locale === 'zh' ? 0 : 1]; setPendingAbility(null); setAbilityActivation({ racer: { ...currentRacer }, ownerName, label }); if (action === 'rocket' || action === 'magician' || action === 'genius' || action === 'legs') { handleRoll(action); return; } playSound('event'); const from = currentRacer.position; const next = activateAbility(state, currentRacer.id, action, targetId); setState(next); setActiveAbility(null); setToast(next.log[next.log.length - 1] ?? null); const moved = next.racers.find((item) => item.id === currentRacer.id); if (moved) beginPieceMovement(moved.id, from, moved.position); };
  const dismissAbilityActivation = useCallback(() => setAbilityActivation(null), []);
  const draftOrderList = state?.phase === 'draft' && draft ? draftOrder(state.players.length, draft.startPlayer) : []; const draftActorIndex = draft ? draftOrderList[draft.pick] : undefined; const draftActor = draftActorIndex === undefined ? undefined : state?.players[draftActorIndex];
  const draftPick = draft?.pick; const draftPoolKey = draft?.pool.join('|');
  useEffect(() => {
    if (!state || state.phase !== 'draft' || !draft || !draftActor?.isAi || !draft.pool.length) return;
    const timer = window.setTimeout(() => { const choice = [...draft.pool].sort((left, right) => racerByName(right).speed - racerByName(left).speed)[0]; if (choice) chooseDraftRacer(choice, true); }, 520);
    return () => window.clearTimeout(timer);
  // The draft identity keys above intentionally control this timer; the callback must use the latest state snapshot.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state, draftPick, draftPoolKey, draftActorIndex]);
  useEffect(() => {
    if (!state || state.phase !== 'race-select') return;
    const player = state.players[state.raceSelectPlayer];
    if (!player) return;
    if (!player.isAi) return;
    const timer = window.setTimeout(() => { const choices = [...player.team].sort((left, right) => racerByName(right).speed - racerByName(left).speed).slice(0, raceSlots(state.players.length)); commitRaceChoice(choices); }, 620);
    return () => window.clearTimeout(timer);
  // The race-selection identity controls this timer; commitRaceChoice reads the current snapshot.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state?.phase, state?.raceSelectPlayer, state?.raceNumber, state?.raceSelections]);
  const movementId = movement?.racerId; const movementFrom = movement?.from; const movementTo = movement?.to;
  useEffect(() => { if (!movementId || movementFrom === undefined || movementTo === undefined) return; const direction = Math.sign(movementTo - movementFrom); const distance = Math.abs(movementTo - movementFrom); if (!direction || !distance) return; let step = 0; let finishTimer: number | undefined; const timer = window.setInterval(() => { step += 1; const nextPosition = movementFrom + direction * step; setMovement((current) => current ? { ...current, position: nextPosition } : null); if (step >= distance) { window.clearInterval(timer); finishTimer = window.setTimeout(() => { setMovement((current) => current?.racerId === movementId ? null : current); playSound(state?.phase === 'result' ? 'finish' : 'move'); }, 180); } }, 180); return () => { window.clearInterval(timer); if (finishTimer) window.clearTimeout(finishTimer); }; }, [movementId, movementFrom, movementTo, playSound, state?.phase]);
  useEffect(() => { if (!state || state.phase !== 'race' || state.mode !== 'ai' || movement || diceRoll || pendingAbility || abilityActivation || mastermindPromptVisible) return; const player = state.players[state.currentPlayer]; if (player?.isAi) { const timer = window.setTimeout(() => { const racer = state.racers.find((r) => r.ownerId === player.id && !r.eliminated && r.finished === null); if (racer?.tripped) return; const from = racer?.position; const aiAction = racer ? abilityActions(state, racer).find((option) => ['rocket', 'magician', 'genius', 'legs'].includes(option.id))?.id : undefined; const next = takeTurn(state, player.id, { ability: aiAction, prediction: aiAction === 'genius' ? 3 : undefined }); if (racer && aiAction) setAbilityActivation({ racer: { ...racer }, ownerName: player.name, label: abilityLabels[aiAction][locale === 'zh' ? 0 : 1] }); setState(next); setToast(next.log[next.log.length - 1] ?? null); const moved = racer && next.racers.find((item) => item.id === racer.id); if (moved && from !== undefined) queueDice(moved.id, from, moved.position, moved.lastRoll); }, 680); return () => window.clearTimeout(timer); } }, [state, movement, diceRoll, pendingAbility, abilityActivation, locale, mastermindPromptVisible]);
  const dicePhase = diceRoll?.phase; const diceRacerId = diceRoll?.racerId; const diceFrom = diceRoll?.from; const diceTo = diceRoll?.to; const diceValue = diceRoll?.value;
  useEffect(() => { if (!dicePhase || !diceRacerId || diceFrom === undefined || diceTo === undefined) return; const timer = window.setTimeout(() => { if (dicePhase === 'rolling') { playSound('event'); setDiceRoll((current) => current ? { ...current, phase: 'result' } : null); } else { setDiceRoll(null); beginPieceMovement(diceRacerId, diceFrom, diceTo); } }, dicePhase === 'rolling' ? 620 : 420); return () => window.clearTimeout(timer); }, [dicePhase, diceRacerId, diceFrom, diceTo, playSound]);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if (event.code === 'Space' && state?.phase === 'race' && !state.players[state.currentPlayer]?.isAi) { event.preventDefault(); handleRoll(); } }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); });
  const currentRacer = state?.racers.find((r) => r.ownerId === state.players[state.currentPlayer]?.id && !r.eliminated && r.finished === null);
  const mastermindRacer = state?.racers.find((racer) => racer.name === 'Mastermind' && !racer.eliminated);
  const mastermindPromptVisible = Boolean(state?.phase === 'race' && mastermindRacer && state.mastermindPrediction === null);
  const confirmMastermind = () => { if (!state || !mastermindRacer || !mastermindTarget || !mastermindPromptVisible) return; const target = state.racers.find((racer) => racer.id === mastermindTarget); if (!target) return; setState({ ...state, mastermindPrediction: { mastermindId: mastermindRacer.id, targetId: target.id } }); setMastermindTarget(null); setToast(locale === 'zh' ? `阴谋家预言：${displayRacerName(target.name, locale)} 获胜。` : `Mastermind predicts ${target.name} will win.`); };
  useEffect(() => {
    if (!mastermindPromptVisible || !state || !mastermindRacer) return;
    const owner = state.players.find((player) => player.id === mastermindRacer.ownerId);
    if (!owner?.isAi) return;
    const timer = window.setTimeout(() => { const target = [...state.racers].filter((racer) => !racer.eliminated).sort((left, right) => racerByName(right.name).speed - racerByName(left.name).speed)[0]; if (target) { setState({ ...state, mastermindPrediction: { mastermindId: mastermindRacer.id, targetId: target.id } }); setToast(`阴谋家预言：${racerByName(target.name).zhName} 获胜。`); } }, 720);
    return () => window.clearTimeout(timer);
  }, [mastermindPromptVisible, state, mastermindRacer]);
  useEffect(() => {
    if (!state || state.phase !== 'race' || !currentRacer?.tripped || movement || diceRoll || pendingAbility || abilityActivation) return;
    const racerSnapshot = { ...currentRacer };
    const revealTimer = window.setTimeout(() => { setTripNotice(racerSnapshot); playSound('event'); }, 0);
    const skipTimer = window.setTimeout(() => {
      const next = takeTurn(state);
      setState(next);
      setToast(next.log[next.log.length - 1] ?? null);
      setTripNotice(null);
    }, 900);
    return () => { window.clearTimeout(revealTimer); window.clearTimeout(skipTimer); };
  }, [state, currentRacer, movement, diceRoll, pendingAbility, abilityActivation, playSound]);
  const pendingTarget = pendingAbility?.targetId ? state?.racers.find((racer) => racer.id === pendingAbility.targetId) : undefined;
  const draftRoundNumber = draft ? Math.floor(draft.pick / (state?.players.length ? state.players.length * 2 : 1)) + 1 : 1;
  const draftTeam = draftActor?.team ?? [];
  if (!state) return <><HomeScreen locale={locale} setLocale={setLocale} mode={mode} setMode={setMode} onStart={start} soundOn={soundOn} setSoundOn={setSoundOn} onUpload={handleUpload} assetCount={Object.keys(assetPack).length} uploadMessage={uploadMessage} />{namePrompt ? <PlayerNameOverlay locale={locale} value={playerName} onChange={setPlayerName} onConfirm={() => { setNamePrompt(false); start(); }} onCancel={() => setNamePrompt(false)} /> : null}</>;
  if (state.phase === 'room') return <main className="app-shell room-shell"><header className="app-header"><div className="brand-lockup"><span className="brand-mark">MA</span><span className="brand-type">MAGICAL<br />ATHLETE</span></div><button className="text-button" onClick={() => setState(null)}>{tx.back}</button></header><section className="room-card"><p className="eyebrow">{tx.room}</p><h1>{state.roomCode}</h1><p>{tx.roomHint}</p><div className="room-code">{state.roomCode?.split('').map((char, i) => <span key={i}>{char}</span>)}</div><button className="primary-cta" onClick={() => { playSound('click'); startDraft({ ...state, phase: 'draft' }); }}>{tx.roomStart}<span>↗</span></button><button className="secondary-cta" onClick={() => { navigator.clipboard?.writeText(state.roomCode ?? ''); setCopied(true); playSound('click'); }}>{copied ? tx.copied : tx.copy}</button><div className="room-players"><span className="status-pip"></span> {state.connected} / 6 {tx.connected}<span className="host-badge">{tx.host}</span></div></section></main>;
  if (state.phase === 'race-select') return <RaceSelectScreen state={state} locale={locale} assetPack={assetPack} selection={raceChoice} onToggle={toggleRaceChoice} onConfirm={() => commitRaceChoice(raceChoice)} onSound={() => playSound('click')} />;
  if (state.phase === 'draft') return <main className="app-shell"><header className="app-header"><div className="brand-lockup"><span className="brand-mark">MA</span><span className="brand-type">MAGICAL<br />ATHLETE</span></div><div className="header-meta"><span>{mode === 'ai' ? tx.ai : mode === 'local' ? tx.local : tx.online}</span><button className="sound-button" onClick={() => setSoundOn(!soundOn)}>{soundOn ? '◉' : '○'}</button><button className="lang-button" onClick={() => setLocale(locale === 'zh' ? 'en' : 'zh')}>{locale === 'zh' ? 'EN' : '中文'}</button></div></header><section className="draft-shell"><div className="section-heading"><div><p className="eyebrow">{tx.draft}</p><h1>{tx.draftTurn.replace('{name}', draftActor?.name ?? tx.waiting)}</h1><small>{tx.draftRound.replace('{n}', String(draftRoundNumber))} · {tx.draftProgress.replace('{n}', String(draft?.pick ?? 0)).replace('{total}', String(state.players.length * 4))}</small></div><div className="draft-count"><strong>{draftTeam.length}</strong><span>/ 4<br />{tx.draftTeam}</span></div></div><div className="draft-grid">{(draft?.pool ?? []).map((name) => { const card = racerByName(name); return <Card key={card.name} card={card} selected={draftTeam.includes(card.name)} onClick={() => chooseDraftRacer(card.name)} locale={locale} assetUrl={assetPack[card.name]} onSound={() => playSound('click')} />; })}</div><div className="draft-assignments">{state.players.map((player) => <DraftAssignment key={player.id} player={player} assetPack={assetPack} locale={locale} />)}</div><div className="draft-bar"><span>{draftActor?.isAi ? tx.draftChoosing : tx.noSelection}</span><span className="draft-order-note">{draft?.pool.length ?? 0} {locale === 'zh' ? '张公开角色卡' : 'face-up racers'} · {draftActor?.name}</span></div></section></main>;
  if (state.phase === 'result' || state.phase === 'game-over') return <main className="app-shell"><header className="app-header"><div className="brand-lockup"><span className="brand-mark">MA</span><span className="brand-type">MAGICAL<br />ATHLETE</span></div><span className="race-pill">{state.phase === 'game-over' ? tx.final : `${tx.race.replace('{n}', String(state.raceNumber))} · ${displayBoardName(state.board, locale)}`}</span></header><section className="result-shell"><p className="eyebrow">{state.phase === 'game-over' ? tx.final : tx.raceResult}</p><h1>{state.phase === 'game-over' ? `${tx.winner.toUpperCase()}.` : tx.finish}</h1><div className="result-grid">{[...state.players].sort((a, b) => b.score - a.score).map((p, i) => <div className={`result-row place-${i + 1}`} key={p.id}><span className="result-place">{String(i + 1).padStart(2, '0')}</span><span className="result-swatch" style={{ background: p.color }}></span><strong>{p.name}</strong><span className="result-score">{p.score} <small>{tx.points}</small></span></div>)}</div><div className="result-actions">{state.phase === 'result' ? <button className="primary-cta" onClick={() => { playSound('click'); setActiveAbility(null); setRaceChoice([]); setState(nextRace(state)); }}>{tx.next}<span>→</span></button> : <button className="primary-cta" onClick={() => { playSound('click'); setState(null); }}>{tx.rematch}<span>↗</span></button>}<button className="text-button" onClick={() => setState(null)}>{tx.back}</button></div></section></main>;
  const activePlayer = state.players[state.currentPlayer];
  return <main className="app-shell"><header className="app-header"><div className="brand-lockup"><span className="brand-mark">MA</span><span className="brand-type">MAGICAL<br />ATHLETE</span></div><div className="race-pill">{tx.race.replace('{n}', String(state.raceNumber))} <span>·</span> {displayBoardName(state.board, locale)}</div><div className="header-controls"><button className="sound-button" onClick={() => setSoundOn(!soundOn)}>{soundOn ? '◉' : '○'}</button><button className="lang-button" onClick={() => setLocale(locale === 'zh' ? 'en' : 'zh')}>{locale === 'zh' ? 'EN' : '中文'}</button></div></header><section className="race-shell"><div className="race-main"><div className="race-heading"><div><p className="eyebrow">{state.board === 'Mild Mile' ? (locale === 'zh' ? '温和大道 · 无事件' : 'MILD MILE · NO EVENTS') : (locale === 'zh' ? '荒野狂奔 · 特殊格' : 'WILD WILDS · SPECIAL SPACES')}</p><h1>{tx.turn}</h1></div><div className="race-number">0{state.raceNumber}<span>/04</span></div></div><Board state={state} locale={locale} assetPack={assetPack} movement={movement} dice={diceRoll} /><div className="turn-strip"><div className="turn-avatar" style={{ background: activePlayer.color }}>{activePlayer.name.slice(-1)}</div><div className="turn-copy"><span>{activePlayer.name}</span><strong>{currentRacer ? displayRacerName(currentRacer.name, locale) : tx.waiting}</strong><small>{currentRacer ? currentRacer.tripped ? tx.tripped : `${tx.move}: ${currentRacer.position} / 30` : tx.waiting}</small></div><div className="die-face" aria-label={`${tx.die}: ${currentRacer?.lastRoll ?? '–'}`}>{currentRacer?.lastRoll ?? '–'}</div><button className="primary-cta roll-button" disabled={!currentRacer || Boolean(activePlayer.isAi) || Boolean(movement || diceRoll || pendingAbility || tripNotice || currentRacer?.tripped)} onClick={() => handleRoll()}>{tx.roll}<span>↗</span></button></div>{currentRacer ? <AbilityPanel state={state} racer={currentRacer} locale={locale} activeAction={activeAbility} prediction={prediction} onAction={handleAbility} onTarget={handleAbility} onPrediction={setPrediction} onCancel={() => setActiveAbility(null)} /> : null}{toast ? <div className="event-toast" role="status">{toast}</div> : null}</div><aside className="race-side"><div className="side-block"><p className="eyebrow">{tx.points}</p>{state.players.map((p) => <div className={`score-row ${p.id === activePlayer.id ? 'is-turn' : ''}`} key={p.id}><span className="score-dot" style={{ background: p.color }}></span><span>{p.name}</span><strong>{p.score}</strong></div>)}</div><div className="side-block team-block"><p className="eyebrow">{tx.ability}</p>{currentRacer && <><div className="ability-card"><Token card={racerByName(currentRacer.name)} assetUrl={assetPack[currentRacer.name]} /><div><strong>{displayRacerName(currentRacer.name, locale)}</strong><span>{locale === 'zh' ? racerByName(currentRacer.name).zhAbility : racerByName(currentRacer.name).ability}</span></div></div><div className="ability-meter"><span style={{ width: `${Math.min(100, currentRacer.position / 30 * 100)}%` }}></span></div><small>{currentRacer.position} / 30 {tx.move}</small></>}</div><div className="side-block log-block"><p className="eyebrow">{tx.log}</p><div className="event-log">{state.log.slice(-7).map((line, i) => <p key={`${line}-${i}`}><span>0{i + 1}</span>{line}</p>)}</div></div></aside></section>{diceRoll ? <DiceOverlay value={diceValue ?? null} phase={dicePhase ?? 'rolling'} locale={locale} /> : null}{tripNotice ? <TripOverlay racer={tripNotice} locale={locale} assetUrl={assetPack[tripNotice.name]} /> : null}{pendingAbility && currentRacer ? <AbilityConfirmOverlay action={pendingAbility.action} racer={currentRacer} target={pendingTarget} prediction={prediction} locale={locale} onPrediction={setPrediction} onConfirm={confirmAbility} onCancel={() => { setPendingAbility(null); setActiveAbility(null); }} /> : null}{abilityActivation ? <AbilityActivationOverlay activation={abilityActivation} locale={locale} assetUrl={assetPack[abilityActivation.racer.name]} onDone={dismissAbilityActivation} /> : null}{mastermindPromptVisible && mastermindRacer ? <MastermindOverlay racers={state.racers} locale={locale} assetPack={assetPack} selectedId={mastermindTarget} onSelect={setMastermindTarget} onConfirm={confirmMastermind} /> : null}</main>;
}
